std::string read(const std::string& path){std::ifstream f(path); if(!f)throw std::runtime_error("Cannot open "+path); std::ostringstream s;s<<f.rdbuf();return s.str();}
GLuint shader(GLenum type,const std::string& path){auto text=read(path);const char* p=text.c_str();GLuint s=glCreateShader(type);glShaderSource(s,1,&p,nullptr);glCompileShader(s);GLint ok;glGetShaderiv(s,GL_COMPILE_STATUS,&ok);if(!ok){char log[8192];glGetShaderInfoLog(s,sizeof(log),nullptr,log);throw std::runtime_error(path+": "+log);}return s;}
GLuint program(const char* a,const char* b){GLuint v=shader(GL_VERTEX_SHADER,std::string("shaders/")+a),f=shader(GL_FRAGMENT_SHADER,std::string("shaders/")+b),p=glCreateProgram();glAttachShader(p,v);glAttachShader(p,f);glLinkProgram(p);glDeleteShader(v);glDeleteShader(f);GLint ok;glGetProgramiv(p,GL_LINK_STATUS,&ok);if(!ok){char log[8192];glGetProgramInfoLog(p,sizeof(log),nullptr,log);throw std::runtime_error(log);}return p;}
GLint loc(GLuint p,const char* n){return glGetUniformLocation(p,n);}
void u(GLuint p,const char*n,int v){glUniform1i(loc(p,n),v);} void u(GLuint p,const char*n,float v){glUniform1f(loc(p,n),v);} void u(GLuint p,const char*n,vec3 v){glUniform3fv(loc(p,n),1,value_ptr(v));} void u(GLuint p,const char*n,vec2 v){glUniform2fv(loc(p,n),1,value_ptr(v));} void u(GLuint p,const char*n,mat4 v){glUniformMatrix4fv(loc(p,n),1,GL_FALSE,value_ptr(v));}
void bind(GLuint p,const char*n,int slot,GLuint t,GLenum target=GL_TEXTURE_2D){glActiveTexture(GL_TEXTURE0+slot);glBindTexture(target,t);u(p,n,slot);}
GLuint image2D(int w,int h,GLint format,GLenum base,GLenum type,GLint filter=GL_NEAREST){GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexImage2D(GL_TEXTURE_2D,0,format,w,h,0,base,type,nullptr);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,filter);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,filter);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);return t;}
void check(){if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)throw std::runtime_error("Framebuffer incomplete");}
GLuint target(GLuint& f,int w,int h){glGenFramebuffers(1,&f);glBindFramebuffer(GL_FRAMEBUFFER,f);GLuint t=image2D(w,h,GL_RGBA16F,GL_RGBA,GL_FLOAT,GL_LINEAR);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,t,0);check();return t;}
struct Vertex {vec3 p,n;vec2 uv;};
