vec3 Indoor::forward()const{float a=radians(yaw),b=radians(pitch);return normalize(vec3(cos(a)*cos(b),sin(b),sin(a)*cos(b)));}
void Indoor::load(const std::string& file,bool statue){
    const std::string base="assets/indoor_model/";tinyobj::ObjReader reader;tinyobj::ObjReaderConfig cfg;cfg.mtl_search_path=base;cfg.triangulate=true;if(!reader.ParseFromFile(base+file,cfg))throw std::runtime_error(reader.Error());
    auto& a=reader.GetAttrib();auto& mats=reader.GetMaterials();std::map<std::string,GLuint> cache;
    auto texture=[&](const std::string& name,bool srgb)->GLuint{if(name.empty())return 0;auto key=name+(srgb?"_s":"_l");if(cache.count(key))return cache[key];int x,y,c;stbi_set_flip_vertically_on_load(1);auto* data=stbi_load((base+name).c_str(),&x,&y,&c,4);if(!data)throw std::runtime_error("Texture missing: "+name);GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexImage2D(GL_TEXTURE_2D,0,srgb?GL_SRGB8_ALPHA8:GL_RGBA8,x,y,0,GL_RGBA,GL_UNSIGNED_BYTE,data);glGenerateMipmap(GL_TEXTURE_2D);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);stbi_image_free(data);textures.push_back(t);return cache[key]=t;};
    auto pos=[&](int i){vec3 p(a.vertices[3*i],a.vertices[3*i+1],a.vertices[3*i+2]);if(statue)p=p*.001f+vec3(2.05f,.628725f,-1.9f);return p;};
    std::vector<vec3> smooth(a.vertices.size()/3,vec3(0));
    if(statue)for(auto& sh:reader.GetShapes()){for(size_t k=0;k+2<sh.mesh.indices.size();k+=3){auto a0=sh.mesh.indices[k].vertex_index,a1=sh.mesh.indices[k+1].vertex_index,a2=sh.mesh.indices[k+2].vertex_index;vec3 n=cross(pos(a1)-pos(a0),pos(a2)-pos(a0));smooth[a0]+=n;smooth[a1]+=n;smooth[a2]+=n;}}
    for(auto& shape:reader.GetShapes()){
        std::map<int,std::vector<Vertex>> batches;size_t offset=0;
        for(size_t face=0;face<shape.mesh.num_face_vertices.size();++face){int count=shape.mesh.num_face_vertices[face],mid=shape.mesh.material_ids[face];if(count!=3){offset+=count;continue;}if(statue&&(mid<0||mats[mid].name!="trice")){offset+=count;continue;}auto i0=shape.mesh.indices[offset],i1=shape.mesh.indices[offset+1],i2=shape.mesh.indices[offset+2];vec3 p0=pos(i0.vertex_index),p1=pos(i1.vertex_index),p2=pos(i2.vertex_index);vec3 crossN=cross(p1-p0,p2-p0);vec3 faceN=length(crossN)>1e-10f?normalize(crossN):vec3(0,1,0);
            for(int j=0;j<3;++j){auto i=shape.mesh.indices[offset+j];vec3 n=faceN;if(statue&&length(smooth[i.vertex_index])>1e-12f)n=normalize(smooth[i.vertex_index]);if(i.normal_index>=0){int k=3*i.normal_index;vec3 q(a.normals[k],a.normals[k+1],a.normals[k+2]);if(length(q)>1e-8f)n=normalize(q);}vec2 uv(0);if(i.texcoord_index>=0){int k=2*i.texcoord_index;uv=vec2(a.texcoords[k],a.texcoords[k+1]);}batches[mid].push_back({pos(i.vertex_index),n,uv});}offset+=3;
        }
        for(auto& pair:batches){auto& data=pair.second;if(data.empty())continue;Mesh m;int id=pair.first;if(id>=0){auto& mat=mats[id];m.color=vec3(mat.diffuse[0],mat.diffuse[1],mat.diffuse[2]);m.shine=mat.shininess;m.ambient=vec3(mat.ambient[0],mat.ambient[1],mat.ambient[2]);m.specular=vec3(mat.specular[0],mat.specular[1],mat.specular[2]);m.tex=texture(mat.diffuse_texname,true);m.bump=texture(mat.normal_texname.empty()?mat.bump_texname:mat.normal_texname,false);auto n=mat.name;if(n=="Listva")m.kind=1;if(n=="Glass_-_Architectural"){m.kind=2;}if(n=="Wood_Floor"){m.reflectivity=.65f;}if(statue){m.bump=texture("tricnorm.jpg",false);m.reflectivity=0;}}
            glGenVertexArrays(1,&m.vao);glGenBuffers(1,&m.vbo);glBindVertexArray(m.vao);glBindBuffer(GL_ARRAY_BUFFER,m.vbo);glBufferData(GL_ARRAY_BUFFER,data.size()*sizeof(Vertex),data.data(),GL_STATIC_DRAW);glEnableVertexAttribArray(0);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,p));glEnableVertexAttribArray(1);glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,n));glEnableVertexAttribArray(2);glVertexAttribPointer(2,2,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,uv));m.count=(GLsizei)data.size();meshes.push_back(m);
        }
    }
}
void Indoor::init(){geom=program("geometry.vert","geometry.frag");shadow=program("shadow.vert","shadow.frag");lighting=program("screen.vert","lighting.frag");reflection=program("screen.vert","reflection.frag");blur=program("screen.vert","blur.frag");post=program("screen.vert","post.frag");glGenVertexArrays(1,&quad);load("Grey_White_Room.obj",false);load("trice.obj",true);glEnable(GL_TEXTURE_CUBE_MAP_SEAMLESS);
    glGenFramebuffers(1,&dirF);glBindFramebuffer(GL_FRAMEBUFFER,dirF);dirDepth=image2D(shadowSize,shadowSize,GL_DEPTH_COMPONENT24,GL_DEPTH_COMPONENT,GL_UNSIGNED_INT);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_TEXTURE_2D,dirDepth,0);glDrawBuffer(GL_NONE);glReadBuffer(GL_NONE);check();
    glGenFramebuffers(1,&cubeF);glBindFramebuffer(GL_FRAMEBUFFER,cubeF);glGenTextures(1,&cubeDepth);glBindTexture(GL_TEXTURE_CUBE_MAP,cubeDepth);for(int i=0;i<6;++i)glTexImage2D(GL_TEXTURE_CUBE_MAP_POSITIVE_X+i,0,GL_DEPTH_COMPONENT24,shadowSize,shadowSize,0,GL_DEPTH_COMPONENT,GL_UNSIGNED_INT,nullptr);glTexParameteri(GL_TEXTURE_CUBE_MAP,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_CUBE_MAP,GL_TEXTURE_MAG_FILTER,GL_NEAREST);for(auto p:{GL_TEXTURE_WRAP_S,GL_TEXTURE_WRAP_T,GL_TEXTURE_WRAP_R})glTexParameteri(GL_TEXTURE_CUBE_MAP,p,GL_CLAMP_TO_EDGE);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_TEXTURE_CUBE_MAP_POSITIVE_X,cubeDepth,0);glDrawBuffer(GL_NONE);glReadBuffer(GL_NONE);check();glGenFramebuffers(1,&areaF);glBindFramebuffer(GL_FRAMEBUFFER,areaF);glGenTextures(1,&areaDepth);glBindTexture(GL_TEXTURE_2D_ARRAY,areaDepth);glTexImage3D(GL_TEXTURE_2D_ARRAY,0,GL_DEPTH_COMPONENT24,512,512,6,0,GL_DEPTH_COMPONENT,GL_UNSIGNED_INT,nullptr);glTexParameteri(GL_TEXTURE_2D_ARRAY,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D_ARRAY,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D_ARRAY,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D_ARRAY,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glFramebufferTextureLayer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,areaDepth,0,0);glDrawBuffer(GL_NONE);glReadBuffer(GL_NONE);check();
    Vertex panel[]={{{0,-.70f,-.48f},{1,0,0},{0,0}},{{0,.70f,-.48f},{1,0,0},{0,1}},{{0,.70f,.48f},{1,0,0},{1,1}},{{0,-.70f,-.48f},{1,0,0},{0,0}},{{0,.70f,.48f},{1,0,0},{1,1}},{{0,-.70f,.48f},{1,0,0},{1,0}}};glGenVertexArrays(1,&panelVAO);glGenBuffers(1,&panelVBO);glBindVertexArray(panelVAO);glBindBuffer(GL_ARRAY_BUFFER,panelVBO);glBufferData(GL_ARRAY_BUFFER,sizeof(panel),panel,GL_STATIC_DRAW);glEnableVertexAttribArray(0);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,p));glEnableVertexAttribArray(1);glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,n));glEnableVertexAttribArray(2);glVertexAttribPointer(2,2,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,uv));// Build a unit sphere from latitude/longitude rings.
    std::vector<Vertex> sphere;auto sv=[](int j,int k){float a=pi<float>()*j/24.f,b=two_pi<float>()*k/48.f;vec3 n(sin(a)*cos(b),cos(a),sin(a)*sin(b));return Vertex{n*.22f,n,vec2(k/48.f,j/24.f)};};for(int j=0;j<24;j++)for(int k=0;k<48;k++){auto a=sv(j,k),b=sv(j+1,k),c=sv(j+1,k+1),d=sv(j,k+1);sphere.insert(sphere.end(),{a,b,c,a,c,d});}sphereCount=(GLsizei)sphere.size();glGenVertexArrays(1,&sphereVAO);glGenBuffers(1,&sphereVBO);glBindVertexArray(sphereVAO);glBindBuffer(GL_ARRAY_BUFFER,sphereVBO);glBufferData(GL_ARRAY_BUFFER,sphere.size()*sizeof(Vertex),sphere.data(),GL_STATIC_DRAW);glEnableVertexAttribArray(0);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,p));glEnableVertexAttribArray(1);glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,n));glEnableVertexAttribArray(2);glVertexAttribPointer(2,2,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)offsetof(Vertex,uv));glBindFramebuffer(GL_FRAMEBUFFER,0);
}
void Indoor::resize(int x,int y){if(x==w&&y==h)return;GLuint oldF[]={gF,hdrF,refF,blurF[0],blurF[1]},oldT[]={gPos,gNorm,gAlb,gMat,gAmbient,gDepth,hdr,ref,blurT[0],blurT[1]};glDeleteFramebuffers(5,oldF);glDeleteTextures(10,oldT);w=x;h=y;glGenFramebuffers(1,&gF);glBindFramebuffer(GL_FRAMEBUFFER,gF);gPos=image2D(w,h,GL_RGBA16F,GL_RGBA,GL_FLOAT);gNorm=image2D(w,h,GL_RGBA16F,GL_RGBA,GL_FLOAT);gAlb=image2D(w,h,GL_RGBA8,GL_RGBA,GL_UNSIGNED_BYTE);gMat=image2D(w,h,GL_RGBA16F,GL_RGBA,GL_FLOAT);gAmbient=image2D(w,h,GL_RGBA16F,GL_RGBA,GL_FLOAT);GLuint a[]={gPos,gNorm,gAlb,gMat,gAmbient};GLenum attachments[]={GL_COLOR_ATTACHMENT0,GL_COLOR_ATTACHMENT1,GL_COLOR_ATTACHMENT2,GL_COLOR_ATTACHMENT3,GL_COLOR_ATTACHMENT4};for(int i=0;i<5;++i)glFramebufferTexture2D(GL_FRAMEBUFFER,attachments[i],GL_TEXTURE_2D,a[i],0);glDrawBuffers(5,attachments);gDepth=image2D(w,h,GL_DEPTH_COMPONENT24,GL_DEPTH_COMPONENT,GL_UNSIGNED_INT);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_TEXTURE_2D,gDepth,0);check();hdr=target(hdrF,w,h);ref=target(refF,w,h);for(int i=0;i<2;++i)blurT[i]=target(blurF[i],std::max(1,w/2),std::max(1,h/2));glBindFramebuffer(GL_FRAMEBUFFER,0);}
