    if(bloom&&debug==0){glViewport(0,0,std::max(1,w/2),std::max(1,h/2));glUseProgram(blur);for(int i=0;i<6;++i){int idx=i%2;glBindFramebuffer(GL_FRAMEBUFFER,blurF[idx]);bind(blur,"source",0,i==0?ref:blurT[1-idx]);u(blur,"direction",i%2==0?vec2(1,0):vec2(0,1));u(blur,"extractBright",i==0);glDrawArrays(GL_TRIANGLES,0,3);}}
