void Indoor::release(){for(auto& m:meshes){glDeleteVertexArrays(1,&m.vao);glDeleteBuffers(1,&m.vbo);}if(!textures.empty())glDeleteTextures((GLsizei)textures.size(),textures.data());GLuint fs[]={gF,dirF,cubeF,hdrF,refF,blurF[0],blurF[1]},ts[]={gPos,gNorm,gAlb,gMat,gAmbient,gDepth,dirDepth,cubeDepth,hdr,ref,blurT[0],blurT[1]};glDeleteFramebuffers(7,fs);glDeleteTextures(12,ts);for(auto p:{geom,shadow,lighting,reflection,blur,post})glDeleteProgram(p);glDeleteVertexArrays(1,&quad);glDeleteFramebuffers(1,&areaF);glDeleteTextures(1,&areaDepth);glDeleteVertexArrays(1,&panelVAO);glDeleteBuffers(1,&panelVBO);glDeleteVertexArrays(1,&sphereVAO);glDeleteBuffers(1,&sphereVBO);}
